//! Handouts generated by the app, read inside it: a library with reading
//! progress, and a reader with highlighter and notes.

use std::collections::HashMap;

use egui::{
    Color32, CursorIcon, Key, PointerButton, Pos2, Rect, RichText, Sense, Stroke, TextureHandle,
    pos2, vec2,
};
use kg_engine::{
    Command, ContentsEntry, Engine, Highlight, HighlightColor, HighlightId, ReaderState, Reading,
    ReadingId,
};
use rust_i18n::t;

use super::Actions;
use crate::app::{KnowGiverApp, Screen};
use crate::{i18n, theme, widgets};

/// Width of the highlights panel.
const PANEL_WIDTH: f32 = 290.0;
/// Width of an A4 page in points, for fitting pages to the window.
const A4_WIDTH_PT: f32 = 595.0;
/// Page textures kept on the GPU.
const KEPT_TEXTURES: usize = 10;
const ZOOMS: [f32; 6] = [0.6, 0.75, 0.9, 1.0, 1.2, 1.5];
const SELECTION: Color32 = Color32::from_rgba_premultiplied(0x2F, 0x6F, 0x68, 0x40);
/// Text within this many points of the pointer can be selected; a drag that
/// starts farther from any text moves the page instead.
const TEXT_REACH_PT: f32 = 6.0;
/// Middle-click scrolling: no movement this close to where it started, then
/// this many pixels per second for each pixel of distance.
const AUTOSCROLL_DEAD_ZONE: f32 = 12.0;
const AUTOSCROLL_SPEED: f32 = 6.0;

/// What a drag with the left button does on the page.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
enum Tool {
    /// Selects text to highlight (drags away from text still move the page).
    #[default]
    Highlight,
    /// Moves the page.
    Hand,
}

/// The side panel's tab.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
enum Side {
    #[default]
    Highlights,
    Contents,
}

/// Reader state that only the UI needs.
#[derive(Default)]
pub struct ReaderUi {
    /// Index into [`ZOOMS`]; `None` is "fit width" (1.0).
    zoom: Option<usize>,
    textures: HashMap<(ReadingId, usize, u32), TextureHandle>,
    /// Text being selected: page, anchor box and current box.
    drag: Option<(usize, usize, usize)>,
    popup: Option<Popup>,
    scroll_to: Option<usize>,
    /// The reading last shown, to jump to its saved page once.
    shown: Option<ReadingId>,
    tool: Tool,
    side: Side,
    /// The page is being moved with the mouse.
    panning: bool,
    /// Middle-click scrolling: where it started, and whether the button was
    /// held and moved (then releasing it stops).
    autoscroll: Option<(Pos2, bool)>,
    /// The page number being typed.
    page_input: Option<String>,
}

impl ReaderUi {
    /// Scrolls the reader to `page` on the next frame.
    #[cfg(test)]
    pub fn jump_to(&mut self, page: usize) {
        self.scroll_to = Some(page);
    }
}

impl std::fmt::Debug for ReaderUi {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ReaderUi")
            .field("zoom", &self.zoom)
            .field("textures", &self.textures.len())
            .finish_non_exhaustive()
    }
}

/// The small menu over the page: a new highlight, or an existing one.
#[derive(Debug, Clone)]
enum Popup {
    New {
        page: usize,
        first: usize,
        last: usize,
        at: Pos2,
    },
    Edit {
        id: HighlightId,
        color: HighlightColor,
        note: String,
        at: Pos2,
    },
}

pub fn show(app: &mut KnowGiverApp, ui: &mut egui::Ui) {
    let mut actions = Actions::default();
    let Ok(engine) = &app.engine else {
        return;
    };
    match engine.reader() {
        Some(reader) => reader_view(ui, engine, reader, &mut app.ui.reader, &mut actions),
        None => {
            app.ui.reader.shown = None;
            library(ui, engine, &mut actions);
        }
    }
    actions.run(app);
}

fn library(ui: &mut egui::Ui, engine: &Engine, actions: &mut Actions) {
    widgets::header(ui, &t!("reader.title"), &t!("reader.subtitle"));
    if engine.readings().is_empty() {
        widgets::hint(ui, &t!("reader.empty"));
        ui.add_space(6.0);
        if ui.button(t!("reader.go_to_plan")).clicked() {
            actions.go_to(Screen::Plan);
        }
        return;
    }
    egui::ScrollArea::vertical().show(ui, |ui| {
        for reading in engine.readings() {
            reading_card(ui, reading, actions);
            ui.add_space(8.0);
        }
    });
}

fn reading_card(ui: &mut egui::Ui, reading: &Reading, actions: &mut Actions) {
    let p = theme::palette(ui.ctx());
    egui::Frame::new()
        .fill(p.surface)
        .stroke(Stroke::new(1.0, p.border))
        .inner_margin(12)
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.horizontal(|ui| {
                ui.vertical(|ui| {
                    ui.label(
                        RichText::new(&reading.title)
                            .family(theme::strong_family())
                            .size(16.0),
                    );
                    let status = if reading.page_count == 0 {
                        t!("reader.not_opened").into_owned()
                    } else {
                        t!(
                            "reader.pages_read",
                            seen = reading.pages_seen.len().min(reading.page_count),
                            total = reading.page_count
                        )
                        .into_owned()
                    };
                    widgets::hint(
                        ui,
                        &format!(
                            "{} · {status}",
                            t!("reader.created", date = i18n::date(reading.created_on))
                        ),
                    );
                    ui.add(
                        egui::ProgressBar::new(reading.progress())
                            .desired_width(260.0)
                            .desired_height(6.0)
                            .fill(p.accent),
                    );
                });
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if ui.button(t!("reader.delete")).clicked() {
                        actions.send(Command::DeleteReading(reading.id));
                    }
                    if ui.button(t!("reader.open_pdf")).clicked() {
                        crate::app::open_file(std::path::Path::new(&reading.path));
                    }
                    let label = if reading.page_count == 0 {
                        t!("reader.read")
                    } else {
                        t!("reader.continue")
                    };
                    let read = egui::Button::new(RichText::new(label).color(Color32::WHITE))
                        .fill(p.accent);
                    if ui.add(read).clicked() {
                        actions.send(Command::OpenReading(reading.id));
                    }
                });
            });
        });
}

fn reader_view(
    ui: &mut egui::Ui,
    engine: &Engine,
    reader: &ReaderState,
    state: &mut ReaderUi,
    actions: &mut Actions,
) {
    let p = theme::palette(ui.ctx());
    let reading = &reader.reading;
    if state.shown != Some(reading.id) {
        state.shown = Some(reading.id);
        state.scroll_to.get_or_insert(reading.last_page);
        state.drag = None;
        state.popup = None;
        state.textures.clear();
    }

    // Title with the file actions, then a bar to move around the handout.
    ui.horizontal(|ui| {
        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
            let ready = reader.pages.is_some();
            if ui
                .add_enabled(ready, egui::Button::new(t!("reader.export")))
                .clicked()
                && let Some(path) = rfd::FileDialog::new()
                    .set_title(t!("reader.export_title"))
                    .set_file_name(format!(
                        "{}-{}.pdf",
                        t!("handout.file_prefix"),
                        kg_engine::slug(&reading.title)
                    ))
                    .add_filter(t!("handout.pdf_filter"), &["pdf"])
                    .save_file()
            {
                actions.send(Command::ExportReading(path));
            }
            if ui.button(t!("reader.open_pdf")).clicked() {
                crate::app::open_file(std::path::Path::new(&reading.path));
            }
            ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                ui.add(
                    egui::Label::new(
                        RichText::new(&reading.title)
                            .family(theme::heading_family())
                            .size(20.0),
                    )
                    .truncate(),
                );
            });
        });
    });
    ui.horizontal(|ui| {
        if ui.button(t!("reader.back")).clicked() {
            actions.send(Command::CloseReader);
        }
        ui.separator();
        page_navigation(ui, reading, state);
        ui.separator();
        let zoom = state.zoom.unwrap_or(3);
        if ui
            .add_enabled(zoom > 0, egui::Button::new("−"))
            .on_hover_text(t!("reader.zoom_out"))
            .clicked()
        {
            state.zoom = Some(zoom - 1);
        }
        ui.label(format!("{:.0}%", ZOOMS[zoom] * 100.0));
        if ui
            .add_enabled(zoom + 1 < ZOOMS.len(), egui::Button::new("+"))
            .on_hover_text(t!("reader.zoom_in"))
            .clicked()
        {
            state.zoom = Some(zoom + 1);
        }
        ui.separator();
        let hint = t!("reader.tool_hint").into_owned();
        ui.selectable_value(
            &mut state.tool,
            Tool::Highlight,
            t!("reader.tool_highlight"),
        )
        .on_hover_text(hint.as_str());
        ui.selectable_value(&mut state.tool, Tool::Hand, t!("reader.tool_hand"))
            .on_hover_text(hint.as_str());
    });
    ui.add(
        egui::ProgressBar::new(reading.progress())
            .desired_height(4.0)
            .fill(p.accent),
    );
    ui.add_space(6.0);

    let Some(pages) = reader.pages.clone() else {
        ui.horizontal(|ui| {
            if reader.failed {
                widgets::hint(ui, &t!("reader.failed"));
            } else {
                ui.spinner();
                widgets::hint(ui, &t!("reader.loading"));
            }
        });
        return;
    };

    egui::Panel::right("reader_highlights")
        .resizable(false)
        .exact_size(PANEL_WIDTH)
        .frame(egui::Frame::new().inner_margin(egui::Margin {
            left: 14,
            ..Default::default()
        }))
        .show(ui, |ui| side_panel(ui, reader, state, actions));
    keyboard_navigation(ui, reading, state);

    let zoom = ZOOMS[state.zoom.unwrap_or(3)];
    let ppp = ui.ctx().pixels_per_point();
    let scale = ((ui.available_width() - 24.0) / A4_WIDTH_PT * zoom).clamp(0.4, 3.0);
    // Pixels per point for rendering, in steps so zooming reuses images.
    let render_scale = ((scale * ppp * 4.0).round() / 4.0 * 100.0) as u32;
    forget_textures(state, reading.id, reading.last_page, render_scale);

    let mut current = None;
    egui::ScrollArea::both()
        .id_salt(("reader_pages", reading.id))
        .auto_shrink([false, false])
        .show(ui, |ui| {
            let view = ui.clip_rect();
            autoscroll(ui, state, view);
            for page in 0..pages.len() {
                let Some([w, h]) = pages.size(page) else {
                    continue;
                };
                ui.vertical_centered(|ui| {
                    let (rect, response) =
                        ui.allocate_exact_size(vec2(w * scale, h * scale), Sense::click_and_drag());
                    if state.scroll_to == Some(page) {
                        ui.scroll_to_rect(rect, Some(egui::Align::TOP));
                        state.scroll_to = None;
                    }
                    if rect.contains(pos2(rect.center().x, view.center().y)) {
                        current = Some(page);
                    }
                    if ui.is_rect_visible(rect) {
                        draw_page(ui, reader, state, page, rect, scale, render_scale, actions);
                        handle_pointer(ui, reader, state, page, rect, scale, &response);
                    }
                });
                ui.add_space(14.0);
            }
        });
    if let Some(page) = current
        && (page != reading.last_page || !reading.pages_seen.contains(&page))
    {
        actions.send(Command::ReaderGoTo(page));
    }
    popup(ui, engine, state, actions);
}

#[allow(clippy::too_many_arguments)]
fn draw_page(
    ui: &egui::Ui,
    reader: &ReaderState,
    state: &mut ReaderUi,
    page: usize,
    rect: Rect,
    scale: f32,
    render_scale: u32,
    actions: &mut Actions,
) {
    let painter = ui.painter();
    let p = theme::palette(ui.ctx());
    painter.rect_filled(
        rect.translate(vec2(4.0, 4.0)),
        0.0,
        p.shadow.gamma_multiply(0.5),
    );
    painter.rect_filled(rect, 0.0, Color32::WHITE);

    let key = (reader.reading.id, page, render_scale);
    if !state.textures.contains_key(&key)
        && let Some(image) = reader.page_image(page, render_scale)
    {
        let color = egui::ColorImage::from_rgba_premultiplied(
            [image.width as usize, image.height as usize],
            &image.rgba,
        );
        let texture = ui.ctx().load_texture(
            format!("reader-{}-{page}-{render_scale}", reader.reading.id.0),
            color,
            egui::TextureOptions::LINEAR,
        );
        state.textures.insert(key, texture);
    }
    match state.textures.get(&key) {
        Some(texture) => {
            painter.image(
                texture.id(),
                rect,
                Rect::from_min_max(pos2(0.0, 0.0), pos2(1.0, 1.0)),
                Color32::WHITE,
            );
        }
        None => {
            actions.send(Command::RenderPage {
                page,
                scale: render_scale,
            });
            // A softer version while the sharp one is drawn, if any.
            let any = state
                .textures
                .iter()
                .find(|((id, p, _), _)| *id == reader.reading.id && *p == page);
            if let Some((_, texture)) = any {
                painter.image(
                    texture.id(),
                    rect,
                    Rect::from_min_max(pos2(0.0, 0.0), pos2(1.0, 1.0)),
                    Color32::WHITE,
                );
            }
            ui.ctx()
                .request_repaint_after(std::time::Duration::from_millis(60));
        }
    }

    let Some(pages) = &reader.pages else {
        return;
    };
    let to_screen = |r: [f32; 4]| {
        Rect::from_min_max(
            rect.min + vec2(r[0], r[1]) * scale,
            rect.min + vec2(r[2], r[3]) * scale,
        )
    };
    for highlight in reader.highlights.iter().filter(|h| h.page == page) {
        let [r, g, b, a] = highlight.color.rgba();
        let fill = Color32::from_rgba_unmultiplied(r, g, b, a);
        for line in pages.line_rects(page, highlight.first, highlight.last) {
            painter.rect_filled(to_screen(line), 1.0, fill);
        }
        if !highlight.note.is_empty()
            && let Some(first) = pages
                .line_rects(page, highlight.first, highlight.last)
                .first()
        {
            // A note marker in the margin.
            let at = pos2(rect.left() + 10.0, to_screen(*first).center().y);
            painter.circle_filled(at, 4.0, Color32::from_rgb(r, g, b));
        }
    }
    if let Some((drag_page, anchor, current)) = state.drag
        && drag_page == page
    {
        let (first, last) = (anchor.min(current), anchor.max(current));
        for line in pages.line_rects(page, first, last) {
            painter.rect_filled(to_screen(line), 1.0, SELECTION);
        }
    }
}

/// Selecting text to highlight, and clicking a highlight to edit it.
fn handle_pointer(
    ui: &egui::Ui,
    reader: &ReaderState,
    state: &mut ReaderUi,
    page: usize,
    rect: Rect,
    scale: f32,
    response: &egui::Response,
) {
    let Some(pages) = &reader.pages else {
        return;
    };
    let boxes = pages.text(page);
    let at_point = |pos: Pos2| {
        let pt = (pos - rect.min) / scale;
        nearest_box(boxes, pt.x, pt.y)
    };
    let over_text = |pos: Pos2| {
        let pt = (pos - rect.min) / scale;
        boxes.iter().any(|b| {
            pt.x >= b.rect[0] - TEXT_REACH_PT
                && pt.x <= b.rect[2] + TEXT_REACH_PT
                && pt.y >= b.rect[1] - TEXT_REACH_PT
                && pt.y <= b.rect[3] + TEXT_REACH_PT
        })
    };
    if state.autoscroll.is_some() {
        return;
    }
    if response.drag_started_by(PointerButton::Primary)
        && let Some(pos) = response.interact_pointer_pos()
    {
        state.popup = None;
        if state.tool == Tool::Hand || !over_text(pos) {
            state.panning = true;
        } else if let Some(i) = at_point(pos) {
            state.drag = Some((page, i, i));
        }
    }
    if state.panning {
        if response.dragged_by(PointerButton::Primary) {
            ui.scroll_with_delta(response.drag_delta());
        }
        if !ui.input(|i| i.pointer.primary_down()) {
            state.panning = false;
        }
        ui.ctx().set_cursor_icon(CursorIcon::Grabbing);
        return;
    }
    if response.hovered() {
        let grab =
            state.tool == Tool::Hand || response.hover_pos().is_some_and(|pos| !over_text(pos));
        ui.ctx().set_cursor_icon(if grab {
            CursorIcon::Grab
        } else {
            CursorIcon::Text
        });
    }
    if response.dragged()
        && let Some(pos) = response.interact_pointer_pos()
        && let Some(i) = at_point(pos)
        && let Some((drag_page, _, current)) = state.drag.as_mut()
        && *drag_page == page
    {
        *current = i;
    }
    if response.drag_stopped()
        && let Some((drag_page, anchor, current)) = state.drag.take()
        && drag_page == page
        && anchor != current
        && let Some(pos) = response.interact_pointer_pos()
    {
        state.popup = Some(Popup::New {
            page,
            first: anchor.min(current),
            last: anchor.max(current),
            at: pos,
        });
    }
    if response.clicked()
        && let Some(pos) = response.interact_pointer_pos()
    {
        let pt = (pos - rect.min) / scale;
        let hit = reader.highlights.iter().find(|h| {
            h.page == page
                && pages
                    .line_rects(page, h.first, h.last)
                    .iter()
                    .any(|r| pt.x >= r[0] && pt.x <= r[2] && pt.y >= r[1] && pt.y <= r[3])
        });
        state.popup = hit.map(|h| Popup::Edit {
            id: h.id,
            color: h.color,
            note: h.note.clone(),
            at: pos,
        });
    }
}

/// The text box under a point, or the closest one on its line.
fn nearest_box(boxes: &[kg_engine::TextBox], x: f32, y: f32) -> Option<usize> {
    let on_line = boxes
        .iter()
        .enumerate()
        .filter(|(_, b)| y >= b.rect[1] - 2.0 && y <= b.rect[3] + 2.0)
        .min_by(|(_, a), (_, b)| distance_x(a, x).total_cmp(&distance_x(b, x)));
    on_line.map(|(i, _)| i).or_else(|| {
        boxes
            .iter()
            .enumerate()
            .min_by(|(_, a), (_, b)| distance(a, x, y).total_cmp(&distance(b, x, y)))
            .map(|(i, _)| i)
    })
}

fn distance_x(b: &kg_engine::TextBox, x: f32) -> f32 {
    if x < b.rect[0] {
        b.rect[0] - x
    } else if x > b.rect[2] {
        x - b.rect[2]
    } else {
        0.0
    }
}

fn distance(b: &kg_engine::TextBox, x: f32, y: f32) -> f32 {
    let cy = (b.rect[1] + b.rect[3]) / 2.0;
    distance_x(b, x) + (y - cy).abs() * 2.0
}

fn color_swatch(ui: &mut egui::Ui, color: HighlightColor, selected: bool) -> egui::Response {
    let [r, g, b, _] = color.rgba();
    let (rect, response) = ui.allocate_exact_size(vec2(22.0, 22.0), Sense::click());
    let painter = ui.painter();
    painter.circle_filled(rect.center(), 9.0, Color32::from_rgb(r, g, b));
    if selected || response.hovered() {
        painter.circle_stroke(
            rect.center(),
            10.5,
            Stroke::new(1.5, theme::palette(ui.ctx()).text),
        );
    }
    response.on_hover_text(i18n::highlight_color(color))
}

fn popup(ui: &egui::Ui, _engine: &Engine, state: &mut ReaderUi, actions: &mut Actions) {
    let Some(popup) = state.popup.clone() else {
        return;
    };
    let at = match &popup {
        Popup::New { at, .. } | Popup::Edit { at, .. } => *at,
    };
    let p = theme::palette(ui.ctx());
    let mut close = false;
    let mut next = popup.clone();
    egui::Area::new(egui::Id::new("reader_popup"))
        .order(egui::Order::Foreground)
        .fixed_pos(at + vec2(8.0, 10.0))
        .show(ui.ctx(), |ui| {
            egui::Frame::new()
                .fill(p.surface)
                .stroke(Stroke::new(1.5, p.ink))
                .inner_margin(10)
                .show(ui, |ui| match &mut next {
                    Popup::New {
                        page, first, last, ..
                    } => {
                        ui.horizontal(|ui| {
                            ui.label(t!("reader.highlight"));
                            for color in HighlightColor::ALL {
                                if color_swatch(ui, color, false).clicked() {
                                    actions.send(Command::AddHighlight {
                                        page: *page,
                                        first: *first,
                                        last: *last,
                                        color,
                                    });
                                    close = true;
                                }
                            }
                            if ui.small_button("×").clicked() {
                                close = true;
                            }
                        });
                    }
                    Popup::Edit {
                        id, color, note, ..
                    } => {
                        ui.set_width(260.0);
                        ui.horizontal(|ui| {
                            for c in HighlightColor::ALL {
                                if color_swatch(ui, c, *color == c).clicked() {
                                    *color = c;
                                }
                            }
                        });
                        ui.add(
                            egui::TextEdit::multiline(note)
                                .hint_text(t!("reader.note_hint"))
                                .desired_rows(3)
                                .desired_width(f32::INFINITY),
                        );
                        ui.horizontal(|ui| {
                            if ui.button(t!("reader.save")).clicked() {
                                actions.send(Command::UpdateHighlight {
                                    id: *id,
                                    color: *color,
                                    note: note.clone(),
                                });
                                close = true;
                            }
                            if ui
                                .button(RichText::new(t!("reader.remove")).color(p.danger))
                                .clicked()
                            {
                                actions.send(Command::DeleteHighlight(*id));
                                close = true;
                            }
                            if ui.small_button("×").clicked() {
                                close = true;
                            }
                        });
                    }
                });
        });
    state.popup = if close { None } else { Some(next) };
}

fn side_panel(
    ui: &mut egui::Ui,
    reader: &ReaderState,
    state: &mut ReaderUi,
    actions: &mut Actions,
) {
    ui.horizontal(|ui| {
        ui.selectable_value(
            &mut state.side,
            Side::Highlights,
            RichText::new(t!("reader.highlights", count = reader.highlights.len()))
                .family(theme::strong_family()),
        );
        ui.selectable_value(
            &mut state.side,
            Side::Contents,
            RichText::new(t!("reader.contents")).family(theme::strong_family()),
        );
    });
    ui.add_space(4.0);
    match state.side {
        Side::Highlights => highlight_list(ui, reader, state, actions),
        Side::Contents => contents_list(ui, reader, state),
    }
}

fn contents_list(ui: &mut egui::Ui, reader: &ReaderState, state: &mut ReaderUi) {
    if reader.contents.is_empty() {
        widgets::hint(ui, &t!("reader.no_contents"));
        return;
    }
    let p = theme::palette(ui.ctx());
    let current = reader.reading.last_page;
    // The entry the reader is in: the last one starting at or before the page.
    let here = reader.contents.iter().rposition(|c| c.page <= current);
    egui::ScrollArea::vertical()
        .id_salt("reader_contents")
        .auto_shrink([false, false])
        .show(ui, |ui| {
            for (i, entry) in reader.contents.iter().enumerate() {
                if contents_row(ui, entry, here == Some(i), p).clicked() {
                    state.scroll_to = Some(entry.page);
                }
            }
        });
}

fn contents_row(
    ui: &mut egui::Ui,
    entry: &ContentsEntry,
    here: bool,
    p: theme::Palette,
) -> egui::Response {
    let response = ui
        .horizontal(|ui| {
            ui.add_space(f32::from(entry.level) * 14.0);
            let mut title = RichText::new(&entry.title);
            if entry.level == 0 {
                title = title.family(theme::strong_family());
            }
            if here {
                title = title.color(p.accent);
            }
            ui.add(egui::Label::new(title).truncate().selectable(false));
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                widgets::hint(ui, &(entry.page + 1).to_string());
            });
        })
        .response
        .interact(Sense::click());
    if response.hovered() {
        ui.ctx().set_cursor_icon(CursorIcon::PointingHand);
    }
    response
}

/// Previous and next page buttons and the page number, which can be typed.
fn page_navigation(ui: &mut egui::Ui, reading: &Reading, state: &mut ReaderUi) {
    let total = reading.page_count;
    let page = reading.last_page;
    if ui
        .add_enabled(total > 0 && page > 0, egui::Button::new("◀"))
        .on_hover_text(t!("reader.prev_page"))
        .clicked()
    {
        state.scroll_to = Some(page - 1);
    }
    let mut text = state
        .page_input
        .clone()
        .unwrap_or_else(|| (page + 1).to_string());
    let edit = ui.add_enabled(
        total > 0,
        egui::TextEdit::singleline(&mut text)
            .desired_width(34.0)
            .horizontal_align(egui::Align::Center),
    );
    let edit = edit.on_hover_text(t!("reader.go_to_page"));
    if edit.has_focus() {
        state.page_input = Some(text.clone());
    }
    if edit.lost_focus() {
        if ui.input(|i| i.key_pressed(Key::Enter))
            && let Ok(typed) = text.trim().parse::<usize>()
            && total > 0
        {
            state.scroll_to = Some(typed.clamp(1, total) - 1);
        }
        state.page_input = None;
    }
    ui.label(
        RichText::new(t!("reader.of_total", total = total)).color(theme::palette(ui.ctx()).muted),
    );
    if ui
        .add_enabled(page + 1 < total, egui::Button::new("▶"))
        .on_hover_text(t!("reader.next_page"))
        .clicked()
    {
        state.scroll_to = Some(page + 1);
    }
}

/// Page Up / Page Down, Home and End, unless a text field is being typed in.
fn keyboard_navigation(ui: &egui::Ui, reading: &Reading, state: &mut ReaderUi) {
    let total = reading.page_count;
    if total == 0 || ui.ctx().memory(|m| m.focused().is_some()) {
        return;
    }
    let page = reading.last_page;
    let target = ui.input(|i| {
        if i.key_pressed(Key::PageDown) {
            Some((page + 1).min(total - 1))
        } else if i.key_pressed(Key::PageUp) {
            Some(page.saturating_sub(1))
        } else if i.key_pressed(Key::Home) {
            Some(0)
        } else if i.key_pressed(Key::End) {
            Some(total - 1)
        } else {
            None
        }
    });
    if target.is_some() {
        state.scroll_to = target;
    }
}

/// Middle-click scrolling: click the wheel and move the mouse away from the
/// mark to scroll that way, faster the farther it is. Clicking again, any
/// other button or Esc stops it; holding the wheel while moving stops it on
/// release.
fn autoscroll(ui: &egui::Ui, state: &mut ReaderUi, view: Rect) {
    let (pressed, released, other, escape, pointer, dt) = ui.input(|i| {
        (
            i.pointer.button_pressed(PointerButton::Middle),
            i.pointer.button_released(PointerButton::Middle),
            i.pointer.button_pressed(PointerButton::Primary)
                || i.pointer.button_pressed(PointerButton::Secondary),
            i.key_pressed(Key::Escape),
            i.pointer.hover_pos(),
            i.stable_dt.min(0.1),
        )
    });
    match state.autoscroll {
        None => {
            if pressed
                && let Some(pos) = pointer
                && view.contains(pos)
            {
                state.autoscroll = Some((pos, false));
                state.drag = None;
                state.popup = None;
            }
            return;
        }
        Some((origin, held)) => {
            let moved = pointer.is_some_and(|pos| pos.distance(origin) > AUTOSCROLL_DEAD_ZONE);
            if (pressed && !held) || other || escape || (released && held) {
                state.autoscroll = None;
                return;
            }
            let still_down = ui.input(|i| i.pointer.button_down(PointerButton::Middle));
            if still_down && moved {
                state.autoscroll = Some((origin, true));
            }
        }
    }
    let Some((origin, _)) = state.autoscroll else {
        return;
    };
    if let Some(pos) = pointer {
        let speed =
            |d: f32| d.signum() * (d.abs() - AUTOSCROLL_DEAD_ZONE).max(0.0) * AUTOSCROLL_SPEED;
        let offset = pos - origin;
        ui.scroll_with_delta(-vec2(speed(offset.x), speed(offset.y)) * dt);
    }
    ui.ctx().set_cursor_icon(CursorIcon::AllScroll);
    // The mark where scrolling started.
    let painter = ui.ctx().layer_painter(egui::LayerId::new(
        egui::Order::Foreground,
        egui::Id::new("reader_autoscroll"),
    ));
    let p = theme::palette(ui.ctx());
    painter.circle_filled(origin, 13.0, p.surface.gamma_multiply(0.9));
    painter.circle_stroke(origin, 13.0, Stroke::new(1.5, p.ink));
    let arrow = Stroke::new(1.5, p.ink);
    for dir in [
        vec2(0.0, -1.0),
        vec2(0.0, 1.0),
        vec2(-1.0, 0.0),
        vec2(1.0, 0.0),
    ] {
        let tip = origin + dir * 9.0;
        let side = vec2(dir.y, -dir.x) * 3.0;
        painter.line_segment([tip, tip - dir * 3.5 + side], arrow);
        painter.line_segment([tip, tip - dir * 3.5 - side], arrow);
    }
    painter.circle_filled(origin, 1.8, p.ink);
    ui.ctx().request_repaint();
}

fn highlight_list(
    ui: &mut egui::Ui,
    reader: &ReaderState,
    state: &mut ReaderUi,
    actions: &mut Actions,
) {
    let p = theme::palette(ui.ctx());
    if reader.highlights.is_empty() {
        widgets::hint(ui, &t!("reader.no_highlights"));
        return;
    }
    egui::ScrollArea::vertical()
        .id_salt("reader_highlight_list")
        .auto_shrink([false, false])
        .show(ui, |ui| {
            for highlight in &reader.highlights {
                highlight_row(ui, highlight, state, actions, p);
                ui.add_space(6.0);
            }
        });
}

fn highlight_row(
    ui: &mut egui::Ui,
    highlight: &Highlight,
    state: &mut ReaderUi,
    actions: &mut Actions,
    p: theme::Palette,
) {
    let mut removed = false;
    let [r, g, b, _] = highlight.color.rgba();
    let response = egui::Frame::new()
        .stroke(Stroke::new(1.0, p.border))
        .inner_margin(8)
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.horizontal(|ui| {
                let (dot, _) = ui.allocate_exact_size(vec2(10.0, 10.0), Sense::hover());
                ui.painter()
                    .circle_filled(dot.center(), 5.0, Color32::from_rgb(r, g, b));
                widgets::hint(ui, &t!("reader.page_short", page = highlight.page + 1));
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if ui
                        .small_button(RichText::new("×").color(p.danger))
                        .on_hover_text(t!("reader.remove"))
                        .clicked()
                    {
                        actions.send(Command::DeleteHighlight(highlight.id));
                        removed = true;
                    }
                });
            });
            let mut text: String = highlight.text.chars().take(160).collect();
            if text.len() < highlight.text.len() {
                text.push('…');
            }
            ui.label(text);
            if !highlight.note.is_empty() {
                ui.label(RichText::new(&highlight.note).italics().color(p.muted));
            }
        })
        .response
        .interact(Sense::click());
    if response.hovered() {
        ui.ctx().set_cursor_icon(CursorIcon::PointingHand);
    }
    if response.clicked() && !removed {
        state.scroll_to = Some(highlight.page);
    }
    if removed && matches!(&state.popup, Some(Popup::Edit { id, .. }) if *id == highlight.id) {
        state.popup = None;
    }
}

/// Drops textures of other handouts, other zooms, and far-away pages.
fn forget_textures(state: &mut ReaderUi, reading: ReadingId, current: usize, scale: u32) {
    // Other zooms stay for a while: they stand in while a page is redrawn.
    state.textures.retain(|(id, _, _), _| *id == reading);
    while state.textures.len() > KEPT_TEXTURES {
        let farthest = state
            .textures
            .keys()
            .max_by_key(|(_, page, s)| (*s != scale, page.abs_diff(current)))
            .copied();
        match farthest {
            Some(key) => state.textures.remove(&key),
            None => break,
        };
    }
}
